-- =============================================================================
-- Inventory SKUs are generated by the database and can't be edited.
-- Format: first 3 letters of the category + running number, e.g. ING-0001,
-- PAC-0002, DRI-0003. The number comes from one sequence, so every SKU is
-- unique even across categories. Once set, an item's SKU never changes.
-- =============================================================================
create sequence if not exists public.inventory_sku_seq;

-- Start after any numbered SKU that already exists
select setval('public.inventory_sku_seq',
  greatest(1, coalesce((select max((regexp_match(sku, '-(\d+)$'))[1]::bigint) from public.inventory_items), 0) + 1), false);

create or replace function public.set_inventory_sku()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_prefix text;
begin
  if tg_op = 'UPDATE' then
    new.sku := old.sku;                 -- SKUs are permanent
    return new;
  end if;
  if coalesce(trim(new.sku), '') = '' then
    v_prefix := upper(left(regexp_replace(coalesce(new.category, ''), '[^A-Za-z]', '', 'g'), 3));
    if length(v_prefix) < 3 then v_prefix := 'INV'; end if;
    loop
      new.sku := v_prefix || '-' || lpad(nextval('public.inventory_sku_seq')::text, 4, '0');
      exit when not exists (select 1 from public.inventory_items where sku = new.sku);
    end loop;
  end if;
  return new;
end $$;

drop trigger if exists trg_inventory_items_sku on public.inventory_items;
create trigger trg_inventory_items_sku before insert or update on public.inventory_items
  for each row execute function public.set_inventory_sku();

revoke execute on function public.set_inventory_sku() from public, anon, authenticated;
